def _handle_list(target, spec, scope):
    if not spec:
        _iterate = scope[TargetRegistry].get_handler('iterate', target, path=scope[Path])
        try:
            iterator = _iterate(target)
        except Exception as e:
            raise TypeError('failed to iterate on target %r, got error: %r' % (target, e))
        return list(iterator)
    if len(spec) != 1:
        raise BadSpec('expected list spec to have exactly one element, got: %r' % spec)
    subspec = spec[0]
    _iterate = scope[TargetRegistry].get_handler('iterate', target, path=scope[Path])
    try:
        iterator = _iterate(target)
    except Exception as e:
        raise TypeError('failed to iterate on target %r, got error: %r' % (target, e))
