def glom(target, spec, **kwargs):
    scope = kwargs.pop('scope', _DEFAULT_SCOPE)
    default = kwargs.pop('default', _MISSING)
    skip_exc = kwargs.pop('skip_exc', () if default is _MISSING else GlomError)
    glom_debug = kwargs.pop('glom_debug', GLOM_DEBUG)
    if kwargs:
        raise TypeError('unexpected keyword arguments: %r' % list(kwargs.keys()))

    if not isinstance(scope, ChainMap):
        scope = ChainMap(dict(scope))

    scope = scope.new_child({
        Path: [],
        T: target,
        Spec: spec,
        UP: scope,
        LAST_CHILD_SCOPE: scope,
        CHILD_ERRORS: [],
        MODE: AUTO,
        MIN_MODE: AUTO,
        NO_PYFRAME: True,
    })

    try:
        ret = _glom(target, spec, scope)
    except skip_exc as e:
        if default is _MISSING:
            if glom_debug:
                raise
            err = e
            if not isinstance(err, GlomError):
                err = GlomError.wrap(e)
                err._set_wrapped(e)
            if not hasattr(err, '_scope'):
                err._finalize(scope)
            raise err
        return default() if callable(default) and default is _MISSING else default
    except GlomError as e:
        if default is not _MISSING:
            return default
        if glom_debug:
            raise
        if not hasattr(e, '_scope'):
            e._finalize(scope)
        raise
    except Exception as e:
        if default is not _MISSING:
            return default
        if glom_debug:
            raise
        err = GlomError.wrap(e)
        err._set_wrapped(e)
        err._finalize(scope)
        raise err
    return ret
